q2:
WITH ValidBeers AS (SELECT beer FROM serves WHERE serves.bar IN (SELECT bar FROM frequents WHERE drinker LIKE 'B%') GROUP BY beer HAVING COUNT(bar) >= 2),
BeerPrices AS (SELECT serves.beer, serves.price FROM serves FULL OUTER JOIN ValidBeers ON serves.beer = ValidBeers.beer)
SELECT bp.beer, MAX(bp.price) - MIN(bp.price) AS price_gap, AVG(bp.price) AS avg_price FROM BeerPrices bp GROUP BY bp.beer ORDER BY bp.beer;

schema:
CREATE TABLE Bar (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Beer (
    name VARCHAR NOT NULL,
    brewer VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Drinker (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Frequents (
    drinker VARCHAR NOT NULL,
    bar VARCHAR NOT NULL,
    times_a_week SMALLINT NOT NULL,
    PRIMARY KEY (drinker, bar),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (bar) REFERENCES Bar(name)
);

CREATE TABLE Serves (
    bar VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    price DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (bar, beer),
    FOREIGN KEY (bar) REFERENCES Bar(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

CREATE TABLE Likes (
    drinker VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    PRIMARY KEY (drinker, beer),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

counterexample:
