INSERT INTO Beer (name, brewer) VALUES ('BeerA', 'Brewer1'), ('BeerB', 'Brewer2'), ('BeerC', 'Brewer3');
INSERT INTO Drinker (name, address) VALUES ('Bob', 'AddrBob'), ('Alice', 'AddrAlice');
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'Bar1', 3);
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'BeerA', 5.00), ('Bar1', 'BeerB', 6.00);

